package app;
import datastructures.WaitingListQueue;import exceptions.BookingNotFoundException;import exceptions.InvalidRoomException;import model.Admin;import model.Booking;import model.Guest;import model.User;import service.BookingService;import service.ReservationService;import service.RoomService;import service.TariffService;import util.InputHelper;import util.OccupancyReport;import java.util.Scanner;
/** Command-line entry point of the Hotel Room Booking System. */
public class Main{
 static final Scanner sc=new Scanner(System.in);static final RoomService roomService=new RoomService();static final TariffService tariffService=new TariffService();static final BookingService bookingService=new BookingService(tariffService);static final WaitingListQueue waitingList=new WaitingListQueue();static final ReservationService reservationService=new ReservationService(roomService,bookingService,waitingList);private Main(){}
 public static void main(String[]args){System.out.println("===== HOTEL ROOM BOOKING SYSTEM =====");boolean running=true;while(running){System.out.println("\nLogin as:  1. Guest   2. Admin   3. Exit");int c=InputHelper.readInt(sc,"Enter choice: ");switch(c){case 1->guestMenu(new User("guest"));case 2->adminMenu(new Admin("admin"));case 3->{System.out.println("Thank you! Goodbye.");running=false;}default->System.out.println("Invalid choice, try again.");}}}
 static void guestMenu(User user){System.out.println("\nLogged in as "+user.getRole());int c;do{System.out.println("\n--- GUEST MENU ---\n1. View Rooms\n2. Book Room (Room Allocation)\n3. Check-in\n4. Check-out & Bill\n5. Back");c=InputHelper.readInt(sc,"Enter choice: ");switch(c){case 1->roomService.viewRooms();case 2->bookRoom();case 3->checkIn();case 4->checkOut();case 5->{}default->System.out.println("Invalid choice, try again.");}}while(c!=5);}
 static void bookRoom(){try{String n=InputHelper.readString(sc,"Guest name: ");String p=InputHelper.readString(sc,"Phone: ");String t=InputHelper.readString(sc,"Room type (Single/Double/Suite): ");int nights=InputHelper.readPositiveInt(sc,"Number of nights planned: ");reservationService.reserve(new Guest(n,p),t,nights);}catch(InvalidRoomException|IllegalArgumentException e){System.out.println("Booking not created: "+e.getMessage());}}
 static void checkIn(){int id=InputHelper.readPositiveInt(sc,"Booking ID: ");try{bookingService.checkIn(id);}catch(BookingNotFoundException e){System.out.println(e.getMessage());}}
 static void checkOut(){int id=InputHelper.readPositiveInt(sc,"Booking ID: ");int n=InputHelper.readPositiveInt(sc,"Number of nights stayed: ");try{Booking b=bookingService.checkOut(id,n);if(b!=null)reservationService.promoteFromWaitingList(b.getRoomType());}catch(BookingNotFoundException|IllegalArgumentException e){System.out.println(e.getMessage());}}
 static void adminMenu(Admin admin){System.out.println("\nLogged in as "+admin.getRole());int c;do{System.out.println("\n--- ADMIN MENU ---\n1. View Rooms\n2. View All Bookings\n3. View Waiting List\n4. Occupancy Report\n5. Back");c=InputHelper.readInt(sc,"Enter choice: ");switch(c){case 1->roomService.viewRooms();case 2->bookingService.viewBookings();case 3->waitingList.display();case 4->OccupancyReport.print(roomService,bookingService,waitingList);case 5->{}default->System.out.println("Invalid choice, try again.");}}while(c!=5);}
}
